window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fb058125845fe5a1"]={"versions": [{"id": "FIG-fb058125845fe5a1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsmodellierung innerhalb der AUTOSAR-Standardisierungsvorlage (Standardization Template). Das Diagramm definiert die Vererbungshierarchie und Metadaten-Attribute zur Referenzierung von Spezifikationselementen ausgehend von allgemeinen AUTOSAR-Basis-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst eine lineare Spezialisierungskette von vier Klassen sowie zwei erläuternde Notizblöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Referrable</strong> (abstrakte Basisklasse):</li>\n<li>Attribut: <code>+ shortName :Identifier</code></li>\n<li><strong>MultilanguageReferrable</strong>:</li>\n<li>Spezialisiert <code>Referrable</code> (Generalisierungsbeziehung).</li>\n<li>Keine eigenen Attribute im Diagramm ausgewiesen.</li>\n<li><strong>Identifiable</strong>:</li>\n<li>Spezialisiert <code>MultilanguageReferrable</code>.</li>\n<li>Attribute:</li>\n<li><code>+ category :CategoryString [0..1]</code></li>\n<li><code>+ uuid :String [0..1]</code></li>\n<li><strong>SpecElementReference</strong>:</li>\n<li>Spezialisiert <code>Identifiable</code>.</li>\n<li>Attribut:</li>\n<li><code>+ alternativeName :String [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">Notizblöcke:</p>\n<ul class=\"fig-list\">\n<li>Notiz zu <code>shortName</code>: „shortName shall match the id or name of a specification element if that id or name is valid with respect to the shortName rules.“</li>\n<li>Notiz zu <code>alternativeName</code>: „alternativeName shall match the id or name of the referenced specification if the id or name is not valid with respect to the shortName rules (e.g. contains spaces, invalid characters, name too long),“</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein rein statisches Metamodell ohne dynamische Abläufe, Zustandsübergänge oder Nachrichtensequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Implementierungen von Modellierungs- und Autorentools gelten folgende normative Modellierungsregeln:</p>\n<ul class=\"fig-list\">\n<li>Wenn der Bezeichner oder Name eines referenzierten Spezifikationselements den syntaktischen Regeln für einen AUTOSAR-<code>shortName</code> genügt, muss dieser Wert als <code>shortName</code> verwendet werden.</li>\n<li>Entspricht der Bezeichner oder Name nicht den <code>shortName</code>-Regeln (z. B. durch Leerzeichen, unzulässige Zeichen oder unzulässige Länge), ist er im optionalen Attribut <code>alternativeName</code> abzubilden.</li>\n<li><code>SpecElementReference</code> erbt die Identifizierungs- und Referenzierungsmerkmale der Basisklassen (<code>shortName</code>, <code>category</code>, <code>uuid</code>).</li>\n</ul>"}, {"id": "FIG-781345e9c0782a64", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsmodellierung innerhalb der AUTOSAR-Standardisierungsvorlage (Standardization Template). Das Diagramm definiert die Vererbungshierarchie und Metadaten-Attribute zur Referenzierung von Spezifikationselementen ausgehend von allgemeinen AUTOSAR-Basis-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst eine lineare Spezialisierungskette von vier Klassen sowie zwei erläuternde Notizblöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Referrable</strong> (abstrakte Basisklasse):</li>\n<li>Attribut: <code>+ shortName: Identifier</code></li>\n<li><strong>MultilanguageReferrable</strong>:</li>\n<li>Spezialisiert <code>Referrable</code> (Generalisierungsbeziehung).</li>\n<li>Keine eigenen Attribute im Diagramm ausgewiesen.</li>\n<li><strong>Identifiable</strong>:</li>\n<li>Spezialisiert <code>MultilanguageReferrable</code>.</li>\n<li>Attribute:</li>\n<li><code>+ category: CategoryString [0..1]</code></li>\n<li><code>+ uuid: String [0..1]</code></li>\n<li><strong>SpecElementReference</strong>:</li>\n<li>Spezialisiert <code>Identifiable</code>.</li>\n<li>Attribut:</li>\n<li><code>+ alternativeName: String [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">Notizblöcke:</p>\n<ul class=\"fig-list\">\n<li>Notiz zu <code>shortName</code>: „shortName shall match the id or name of a specification element if that id or name is valid with respect to the shortName rules.“</li>\n<li>Notiz zu <code>alternativeName</code>: „alternativeName shall match the id or name of the referenced specification if the id or name is not valid with respect to the shortName rules (e.g. contains spaces, invalid characters, name too long),“</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein rein statisches Metamodell ohne dynamische Abläufe, Zustandsübergänge oder Nachrichtensequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Implementierungen von Modellierungs- und Autorentools gelten folgende normative Modellierungsregeln:</p>\n<ul class=\"fig-list\">\n<li>Wenn der Bezeichner oder Name eines referenzierten Spezifikationselements den syntaktischen Regeln für einen AUTOSAR-<code>shortName</code> genügt, muss dieser Wert als <code>shortName</code> verwendet werden.</li>\n<li>Entspricht der Bezeichner oder Name nicht den <code>shortName</code>-Regeln (z. B. durch Leerzeichen, unzulässige Zeichen oder unzulässige Länge), ist er im optionalen Attribut <code>alternativeName</code> abzubilden.</li>\n<li><code>SpecElementReference</code> erbt die Identifizierungs- und Referenzierungsmerkmale der Basisklassen (<code>shortName</code>, <code>category</code>, <code>uuid</code>).</li>\n</ul>"}, {"id": "FIG-1674fc258ce56e4f", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikationsmodellierung innerhalb der AUTOSAR-Standardisierungsvorlage (Standardization Template). Das Diagramm definiert die Vererbungshierarchie und Metadaten-Attribute zur Referenzierung von Spezifikationselementen ausgehend von allgemeinen AUTOSAR-Basis-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst eine lineare Spezialisierungskette von vier Klassen sowie zwei erläuternde Notizblöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Referrable</strong> (abstrakte Basisklasse):</li>\n<li>Stereotyp / Eigenschaft am Attribut: <code>«atpIdentityContribu...</code> (<code>«atpIdentityContributor»</code>)</li>\n<li>Attribut: <code>+ shortName: Identifier</code></li>\n<li><strong>MultilanguageReferrable</strong>:</li>\n<li>Spezialisiert <code>Referrable</code> (Generalisierungsbeziehung).</li>\n<li>Keine eigenen Attribute im Diagramm ausgewiesen.</li>\n<li><strong>Identifiable</strong>:</li>\n<li>Spezialisiert <code>MultilanguageReferrable</code>.</li>\n<li>Attribute:</li>\n<li><code>+ category: CategoryString [0..1]</code></li>\n<li><code>+ uuid: String [0..1]</code></li>\n<li><strong>SpecElementReference</strong>:</li>\n<li>Spezialisiert <code>Identifiable</code>.</li>\n<li>Attribut:</li>\n<li><code>+ alternativeName: String [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">Notizblöcke:</p>\n<ul class=\"fig-list\">\n<li>Notiz zu <code>shortName</code>: „shortName shall match the id or name of a specification element if that id or name is valid with respect to the shortName rules.“</li>\n<li>Notiz zu <code>alternativeName</code>: „alternativeName shall match the id or name of the referenced specification if the id or name is not valid with respect to the shortName rules (e.g. contains spaces, invalid characters, name too long),“</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein rein statisches Metamodell ohne dynamische Abläufe, Zustandsübergänge oder Nachrichtensequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Implementierungen von Modellierungs- und Autorentools gelten folgende normative Modellierungsregeln:</p>\n<ul class=\"fig-list\">\n<li>Das Attribut <code>shortName</code> ist mit dem Stereotyp <code>«atpIdentityContributor»</code> versehen und fungiert als Identitätsbeitrag im Modellierungskontext.</li>\n<li>Wenn der Bezeichner oder Name eines referenzierten Spezifikationselements den syntaktischen Regeln für einen AUTOSAR-<code>shortName</code> genügt, muss dieser Wert als <code>shortName</code> verwendet werden.</li>\n<li>Entspricht der Bezeichner oder Name nicht den <code>shortName</code>-Regeln (z. B. durch Leerzeichen, unzulässige Zeichen oder unzulässige Länge), ist er im optionalen Attribut <code>alternativeName</code> abzubilden.</li>\n<li><code>SpecElementReference</code> erbt die Identifizierungs- und Referenzierungsmerkmale der Basisklassen (<code>shortName</code>, <code>category</code>, <code>uuid</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-fb058125845fe5a1", "to": "FIG-781345e9c0782a64", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Formatierung der Typ-Annotationen bei Attributen vereinheitlicht: Bei <code>shortName: Identifier</code>, <code>category: CategoryString [0..1]</code>, <code>uuid: String [0..1]</code> und <code>alternativeName: String [0..1]</code> wurde das Leerzeichen vor dem Doppelpunkt entfernt (<code>: Type</code> statt <code> :Type</code>).</li>\n<li>Typografischer Neu-Umbruch des Texts in den beiden Notizblöcken rechts (Zeilenumbrüche angepasst, ohne Textänderung).</li>\n</ul>"}, {"from": "FIG-781345e9c0782a64", "to": "FIG-1674fc258ce56e4f", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>Referrable</code>: Dem Attribut <code>shortName</code> wurde der Stereotyp <code>«atpIdentityContributor»</code> (im Diagramm trunkiert dargestellt als <code>«atpIdentityContribu...</code>) hinzugefügt.</li>\n</ul>"}]};
